```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        // Read the clock once; this is the only time source the node uses.
        let seconds = crate::wasi::clocks::wall_clock::now().seconds;

        // One permitted fetch. Transport failures come back as Err values and
        // are reported as zero characters fetched; out-of-allowlist requests
        // trap at the boundary.
        let fetched = match crate::aap::caps::http_client::fetch(&feed_url) {
            Ok(body) => u32::try_from(body.chars().count()).unwrap_or(u32::MAX),
            Err(_) => 0,
        };

        // Report the notifier's actual answer rather than asserting success.
        let message = format!("heartbeat seconds={seconds} fetched={fetched}");
        let notified = crate::aap::caps::notifier::notify(&message);

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
